class SyncJob
{
    void Run(BlogContext context)
    {
        var blogs = context.Blogs.ToList();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }

        // Breaking change 4: EF Core 9 Cosmos provider uses patch (partial update) by default
        // instead of full document replace. Use full-replace if you need the old behavior:
        context.SaveChanges();
    }

    // Breaking change 5: Raw SQL queries must use the new property name.
    // Old: SELECT * FROM c WHERE c.Discriminator = 'Blog'
    // Fix: If you kept "Discriminator" via HasDiscriminator (as done above), no SQL change needed.
    // Otherwise change to: SELECT * FROM c WHERE c["$type"] = 'Blog'
}

